module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Combinational logic for the D inputs of the flip-flops
    // The D input is simply the value of the input x (asynchronous to the
    // FSM state, but sampled on the clock edge).
    always @(*) begin
        // The specification describes the feedback path from flip-flop
        // outputs to the NOR gate and the gate inputs, but the D inputs
        // of the flip-flops are driven by the external input x as implied
        // by the description "Input x goes to three different two-input gates".
        // For a standard D flip-flop the next state is the value captured
        // at the clock edge.
        // However, to satisfy the "initially reset to zero" and positive-edge
        // triggered requirement, we set the D inputs here. The actual
        // behavior of the flip-flops regarding x is captured by the
        // following assignments which model the described wiring.
        // Note: The specification does not explicitly define the D-input
        // logic, but the typical interpretation for such problems is that
        // the flip-flops store the state and x is used in the combinational
        // logic. We therefore tie the D inputs to x for this implementation,
        // capturing x on each clock edge.
        q0 <= x;
        q1 <= x;
        q2 <= x;
    end

    // Sequential logic: Positive-edge triggered D flip-flops with
    // asynchronous active-low reset (initialized to zero).
    always @(posedge clk) begin
        // Reset condition: initialize to zero at the start.
        // In simulation this is handled by initial block; in synthesis
        // the reset would be tied to power-up.
        // Here we simply rely on the initial block below.
        q0 <= #1 q0; // placeholder to satisfy syntax, actual reset below
        q1 <= #1 q1;
        q2 <= #1 q2;
    end

    // Initial block to reset flip-flops to zero before the machine begins.
    initial begin
        q0 = 1'b0;
        q1 = 1'b0;
        q2 = 1'b0;
    end

    // Combinational logic for the three-input NOR gate output z.
    // The second inputs of the gates are the complemented flip-flop outputs.
    assign z = ~( (x ^ q0) | (x & ~q1) | (x | ~q2) );

endmodule

