module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00, // Initial state, waiting for the first '1'
        S_1      = 2'b01, // Matched the first '1'
        S_11     = 2'b10, // Matched '11'
        S_110    = 2'b11  // Matched '110'
    } state_t;

    state_t   state, next_state;
    logic     found; // Internal flag to capture the match

    // State transition logic (sequential, positive edge triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_IDLE;
            found <= 1'b0;
        end else begin
            state <= next_state;
            // Once the sequence 1101 is found, 'found' stays 1 forever
            // (until reset, which is handled above)
            if (state == S_110 && data == 1'b1) begin
                found <= 1'b1;
            end
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_IDLE:     // Waiting for first '1'
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;

            S_1:        // Have seen a '1', waiting for second '1'
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE; // Reset if next bit is '0'

            S_11:       // Have seen '11', waiting for '0'
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_1; // If '1', stay in S_1 (overlap possibility, though spec doesn't require it, standard pattern matching keeps state)

            S_110:      // Have seen '110', waiting for final '1'
                if (data == 1'b1)
                    next_state = S_110; // Stay in final state (or could go to S_1, but keeping here maintains the 'found' flag logic simply)
                else
                    next_state = S_IDLE;

            default:    next_state = S_IDLE;
        endcase
    end

    // Output logic
    // start_shifting is 1 once the sequence is found, forever until reset
    assign start_shifting = found;

endmodule

