module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum reg [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    reg [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        // Store first byte
                        shift_reg <= {in, 16'b0};
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    shift_reg <= {shift_reg[15:0], in};
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    shift_reg <= {shift_reg[7:0], in};
                end

                BYTE3: begin
                    // Third byte received: assert done and output message
                    next_state <= IDLE;
                    done         <= 1'b1;
                    out_bytes    <= shift_reg;
                end
            endcase
        end
    end

endmodule

