    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Derived variables for K-map rows and columns
    // Row: x3 x4  -> here x3 is the row select, x4 is x[2] (since x[3:0] mapping: x3 is MSB)
    // Actually, the K-map rows are x[3]x[4]. Given x is 4 bits (x[3:0]),
