    wire s0, s1, s2;
    assign s0 = s[0];
    assign s1 = s[1];
    assign s2 = s[2];

    reg [1:0] state;
    reg fr0_reg, fr1_reg, fr2_reg, dfr_reg;

    // State encoding: 
    // 2'b00: Below s[0] (all outputs high)
    // 2'b01: Between s[1] and s[0] (fr0, fr1)
    // 2'b10: Between s[2] and s[1] (fr0)
    // 2'b11: Above s[2] (none)

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            fr0_reg <= 1'b1;
            fr1_reg <= 1'b1;
            fr2_reg <= 1'b1;
            dfr_reg <= 1'b1;
        end else begin
            // Default assignments (hold current state unless transition)
            fr0_reg <= fr0_reg;
            fr1_reg <= fr1_reg;
            fr2_reg <= fr2_reg;
            dfr_reg <= dfr_reg;

            case (state)
                2'b00: begin // Below s[0]
                    if (!s0 && !s1 && !s2) begin
                        // Stay in below s[0]
                    end else if (s0) begin
                        // Transition to between s[1] and s[0]
                        state <= 2'b01;
                        fr1_reg <= 1'b0;
                    end else if (s1) begin
                        // Transition to between s[2] and s[1]
                        state <= 2'b10;
                        fr1_reg <= 1'b1;
                    end else if (s2) begin
                        // Transition to above s[2]
                        state <= 2'b11;
                        fr2_reg <= 1'b0;
                        dfr_reg <= 1'b0;
                    end
                end
                2'b01: begin // Between s[1] and s[0]
                    if (!s0 && !s1 && !s2) begin
                        // Drop to below s[0]
                        state <= 2'b00;
                        fr1_reg <= 1'b1;
                        fr2_reg <= 1'b1;
                        dfr_reg <= 1'b1;
                    end else if (!s0 && s1) begin
                        // Stay or transition up? Specification: level between upper and lower.
                        // If previous level was lower than current, increase flow.
                        // Here we assume staying or moving based on s.
                        // To satisfy "increase by opening Supplemental", we toggle dfr if level rises.
                        // Since s1 is asserted and s0 de-asserted, level rose.
                        dfr_reg <= 1'b1; // Open supplemental
                    end else if (s0) begin
                        // Stay in interval
                    end
                end
                2'b10: begin // Between s[2] and s[1]
                    if (!s0 && !s1 && !s2) begin
                        // Drop to below s[0]
                        state <= 2'b00;
                        fr1_reg <= 1'b1;
                        fr2_reg <= 1'b1;
                        dfr_reg <= 1'b1;
                    end else if (!s1 && s2) begin
                        // Level dropped, maybe stay or adjust.
                        // If previous level was higher than current, we might need to adjust.
                        // Specification: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased"
                        // Here previous (state) was between s2 and s1, current is between s1 and s0 (level dropped?).
                        // Actually if s2 asserted and s1 de-asserted, level dropped.
                        // We will just hold outputs for now, or adjust dfr based on logic.
                        // To be safe, we set dfr based on comparison.
                        // Since level dropped, we do not increase dfr.
                    end else if (s0) begin
                        // Moved to between s[1] and s[0]
                        state <= 2'b01;
                        fr1_reg <= 1'b0;
                    end
                end
                2'b11: begin // Above s[2]
                    if (!s0 && !s1 && !s2) begin
                        // Drop to below s[0]
                        state <= 2'b00;
                        fr1_reg <= 1'b1;
                        fr2_reg <= 1'b1;
                        dfr_reg <= 1'b1;
                    end else begin
                        // Stay above s[2], flow zero
                        fr2_reg <= 1'b0;
                        dfr_reg <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Output assignments based on registers
    assign fr0 = fr0_reg;
    assign fr1 = fr1_reg;
    assign fr2 = fr2_reg;
    assign dfr = dfr_reg;

