module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        S_WALK_LEFT,    // 0
        S_WALK_RIGHT,   // 1
        S_FALLING,      // 2
        S_DIGGING,      // 3
        S_SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Direction register - tracks walking direction during fall/dig
    typedef enum logic [1:0] {
        DIR_LEFT,
        DIR_RIGHT
    } dir_t;
    dir_t dir, next_dir;

    // Fall counter - counts consecutive cycles with ground=0
    logic [4:0] fall_count, next_fall_count; // 5 bits (0-31)

    // Outputs (Moore machine - outputs depend only on state)
    assign walk_left   = (state == S_WALK_LEFT);
    assign walk_right  = (state == S_WALK_RIGHT);
    assign aaah        = (state == S_FALLING);
    assign digging     = (state == S_DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
            dir <= DIR_LEFT;
            fall_count <= 0;
        end else begin
            state <= next_state;
            dir <= next_dir;
            fall_count <= next_fall_count;
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state;
        next_dir = dir;
        next_fall_count = fall_count;

        case (state)
            S_WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappeared -> fall
                    next_state = S_FALLING;
                    next_dir = DIR_LEFT; // Preserve direction
                    next_fall_count = 1;
                end else if (dig) begin
                    // Start digging
                    next_state = S_DIGGING;
                    next_dir = DIR_LEFT; // Preserve direction
                end else begin
                    // Check bumps (priority: both > left > right)
                    if (bump_left && bump_right) begin
                        // Bumped on both -> switch direction
                        next_state = S_WALK_RIGHT;
                        next_dir = DIR_RIGHT;
                    end else if (bump_left) begin
                        // Bumped on left -> walk right
                        next_state = S_WALK_RIGHT;
                        next_dir = DIR_RIGHT;
                    end else if (bump_right) begin
                        // Bumped on right -> walk left (no change needed, but explicit)
                        next_state = S_WALK_LEFT;
                        next_dir = DIR_LEFT;
                    end
                    // else stay S_WALK_LEFT
                end
            end

            S_WALK_RIGHT: begin
                if (!ground) begin
                    next_state = S_FALLING;
                    next_dir = DIR_RIGHT;
                    next_fall_count = 1;
                end else if (dig) begin
                    next_state = S_DIGGING;
                    next_dir = DIR_RIGHT;
                end else begin
                    if (bump_left && bump_right) begin
                        next_state = S_WALK_LEFT;
                        next_dir = DIR_LEFT;
                    end else if (bump_left) begin
                        next_state = S_WALK_RIGHT;
                        next_dir = DIR_RIGHT;
                    end else if (bump_right) begin
                        next_state = S_WALK_LEFT;
                        next_dir = DIR_LEFT;
                    end
                end
            end

            S_FALLING: begin
                if (!ground) begin
                    // Still falling, increment counter
                    if (fall_count < 31)
                        next_fall_count = fall_count + 1;
                end else begin
                    // Ground hit!
                    if (fall_count > 20) begin
                        // Splatter! (more than 20 cycles fallen)
                        next_state = S_SPLATTERED;
                    end else begin
                        // Resume walking in preserved direction
                        next_state = (dir == DIR_LEFT) ? S_WALK_LEFT : S_WALK_RIGHT;
                        // Reset fall counter since we're back on ground
                        next_fall_count = 0;
                    end
                end
            end

            S_DIGGING: begin
                if (!ground) begin
                    // Ground disappeared while digging -> fall
                    next_state = S_FALLING;
                    next_dir = dir; // Preserve digging direction
                    next_fall_count = 1;
                end else if (!dig) begin
                    // Dig command removed -> stop digging, resume walking
                    next_state = (dir == DIR_LEFT) ? S_WALK_LEFT : S_WALK_RIGHT;
                end else begin
                    // else stay S_DIGGING (ground=1 and dig=1)
                end
            end

            S_SPLATTERED: begin
                // Forever stuck, only reset changes state
                // Inputs have no effect - keep state as SPLATTERED
                next_state = S_SPLATTERED;
            end
        endcase
    end

endmodule
